export interface TvIconProps {
  name: string
  size?: number
  className?: string
  title?: string
}

export function TvIcon({ name, size = 22, className = "", title }: TvIconProps) {
  const rawSvg = TV_RAW_SVGS[name] || TV_RAW_SVGS["LineToolTrendLine"] || ""
  return (
    <span
      title={title}
      className={`inline-flex shrink-0 items-center justify-center leading-none select-none [&>svg]:w-full [&>svg]:h-full [&_.crossed-eye]:hidden [&_.loading-eye]:hidden [&_.animated-loading-eye]:hidden ${className}`}
      style={{ width: size, height: size }}
      dangerouslySetInnerHTML={{ __html: rawSvg }}
    />
  )
}
